CAT = "aereraLeasing"; SEG = "LSE"
# Law No. (26) of 2007 as amended by Law No. (33) of 2008 (landlords and tenants) and Decree No. (26) of 2013
# (Rent Disputes Settlement Centre). Articles 2, 3, 4, 9, 13, 14, 15, 25, 26, 29 and 36 are quoted as amended.
Q = [
("In what form must a lease contract be made under Law No. (26) of 2007?",
 "In writing, signed by both", ["Verbally, with a witness present", "By email exchanged between parties", "By a note written by the broker"],
 "Article 4 regulates the landlord-tenant relationship through a written lease contract signed by both parties."),
("What happens to a dispute over a lease that was never registered (Ejari) with the Land Department?",
 "Courts and government bodies decline it", ["It is heard, but a penalty is added", "Default statutory terms are applied to it", "The broker settles it between them"],
 "Article 4 says judicial authorities and government bodies may not consider a dispute or claim relating to a lease contract unless it is registered. Registration of lease contracts moved from RERA to the Land Department under Article 10 of Law No. (4) of 2019."),
("A lease does not state its term. For how long is it valid?",
 "For the period of rent payment", ["For one calendar year in all cases", "For two years as a default term", "For the term the landlord chooses"],
 "Article 5 deems it valid for the period specified for payment of the rent where the term is not stated or cannot be proved."),
("The term ends but the tenant stays and the landlord does not object. The lease is renewed:",
 "Shorter of old term or one year", ["Month to month until a notice is given", "For two years on the same terms", "For one year in every case"],
 "Article 6 renews it for the same term or for one year, whichever is shorter, on the same terms."),
("May either party end a valid lease unilaterally during its term?",
 "No, only by consent or under the Law", ["Yes, with 30 days' written notice", "Yes, after the first six months", "Yes, by the landlord alone, with notice"],
 "Article 7 says a valid lease may not be unilaterally terminated by landlord or tenant, only by mutual consent or under the Law."),
("When does a sub-lease normally expire?",
 "When the main lease expires", ["After ninety days of occupation", "When the sub-tenant moves out", "On the death of the landlord"],
 "Article 8 ends a sub-lease with the main lease unless the landlord expressly agrees to extend it."),
("The parties left the rent unspecified in the lease. What rent applies?",
 "The rent of similar property", ["The previous tenant's last rent", "The landlord's asking rent for the property", "No rent until the parties agree"],
 "Article 9 as amended says that where the parties omit the rent, it is the rent of similar real property, which the Tribunal determines."),
("When no payment dates were agreed, how is the rent paid?",
 "In four equal advance instalments", ["Monthly, in arrears, in equal parts", "Once, at the end of the lease year", "In two equal instalments, in advance"],
 "Article 12 provides that without agreement the rent is paid annually in four equal instalments, in advance."),
("Unless otherwise agreed, how long before expiry must a party notify the other of a wish to amend terms or not renew?",
 "At least 90 days", ["At least 30 days", "At least 60 days", "At least six months"],
 "Article 14 as amended requires notice not less than ninety days before the lease expires."),
("Unless otherwise agreed, who is responsible for maintenance and repair of defects during the lease?",
 "The landlord", ["The tenant", "The broker", "Both equally"],
 "Article 16 makes the landlord responsible for maintenance and for repairing any defect that may affect the tenant's intended use."),
("May a landlord alter the property so the tenant can no longer use it fully as intended?",
 "No", ["Yes, with 30 days' notice", "Yes, in winter", "Yes, with RERA approval"],
 "Article 17 forbids changes that preclude the tenant from full use as intended, and makes the landlord responsible for them."),
("A tenant needs official approvals for decoration works that do not affect the structure. What must the landlord do?",
 "Provide the approvals needed", ["Refuse the works without a reason", "Charge a fee for each approval", "Carry out the works himself"],
 "Article 18 requires the landlord to provide the approvals to the competent entities where the works do not affect the structure."),
("May a tenant change the property or do restoration works on his own initiative?",
 "No, only with consent and licences", ["Yes, minor works need no approval", "Yes, once six months have passed", "Yes, if he restores the unit later"],
 "Article 19 bars changes, restoration or maintenance works unless the landlord permits them and the licences from competent entities are obtained."),
("What may a landlord take from the tenant to cover maintenance at the end of the lease?",
 "A security deposit", ["A second year's rent", "A bank guarantee only", "A commission"],
 "Article 20 allows a security deposit to ensure maintenance, which the landlord must refund, or the remainder, at expiry."),
("How must the tenant return the property at the end of the term?",
 "As received, except ordinary wear", ["Freshly painted in the landlord's colours", "Better than received, to compensate", "As the landlord later prefers"],
 "Article 21 requires surrender in the same condition as received, except ordinary wear and tear or damage from causes beyond the tenant's control."),
("Unless agreed otherwise, may a tenant remove leasehold improvements on leaving?",
 "No", ["Yes, freely", "Yes, if he repaints", "Yes, after a month"],
 "Article 23 says that unless agreed otherwise the tenant may not remove the improvements he made on vacating."),
("What does a tenant need before sub-letting the property?",
 "The landlord's written consent", ["A prior notice filed with RERA", "A letter from the broker involved", "Dubai Municipality approval"],
 "Article 24 says that unless agreed otherwise the tenant may not assign use or sub-let without the landlord's written consent."),
("Within what period after a notice to pay may a landlord seek eviction for unpaid rent?",
 "30 days", ["7 days", "15 days", "60 days"],
 "Article 25(1) as amended allows eviction where rent is not paid within thirty days of the landlord's notice to pay, unless the parties agree otherwise."),
("Which is a ground to evict a tenant when the lease has expired?",
 "The owner wants to sell the property", ["The tenant requested minor repairs twice", "The rent was once paid a week late", "The tenant brought a pet into the property"],
 "Article 25(2) as amended lists demolition or reconstruction, comprehensive maintenance, the owner's own or a first-degree relative's use, and sale of the leased property."),
("How much notice must a landlord give for an eviction at expiry on those grounds, through a Notary Public or registered post?",
 "12 months", ["30 days", "90 days", "Six months"],
 "Article 25 as amended requires the Landlord to give the reasons twelve months before the date set for eviction."),
("The Tribunal awards a landlord possession for his own use. How long before he may re-let a residential property to a third party?",
 "Two years", ["Six months", "One year", "Five years"],
 "Article 26 as amended bars re-letting before two years for residential property and three years for non-residential property, unless the Tribunal sets a shorter period."),
("After a rebuilt or renovated property is ready, within what time must the former tenant use his right of first refusal?",
 "30 days from notification", ["7 days from notification", "60 days from notification", "90 days from notification"],
 "Article 29 as amended gives the tenant a right of first refusal, to be exercised within thirty days of the landlord's notice."),
("A landlord cuts off services to the property. What may the tenant do?",
 "Go to the police or the Tribunal", ["Move out of the property at once", "Wait for RERA to cancel the lease", "Ask the broker to intervene"],
 "Article 34 lets the tenant go to the local police station or file a damages claim with the Tribunal, supported by official reports."),
("The landlord of a leased property dies during the term. What happens to the lease?",
 "It continues with the heirs", ["It ends on the date of death", "It must be renegotiated in full", "It passes to RERA to manage"],
 "Article 27 says the lease does not expire on the death of the landlord or tenant and continues with the heirs."),
("Which body has exclusive jurisdiction over rent disputes between landlords and tenants in Dubai?",
 "The Rent Disputes Settlement Centre", ["The Land Department Council of four", "Dubai Municipality's legal section", "The Chamber of Commerce arbitration"],
 "Decree No. (26) of 2013 gives the Centre exclusive jurisdiction over rent disputes in the Emirate and its free zones, with listed exceptions."),
("How long does the Mediation and Conciliation Directorate normally try to reach a settlement from the parties' appearance?",
 "15 days", ["3 days", "30 days", "60 days"],
 "Article 10 of Decree No. (26) of 2013 sets fifteen days, extendable for the same period by the supervising judge."),
("What is the time limit to appeal a First Instance Division judgment in a rent dispute?",
 "15 days from the day after hearing", ["7 days from the date of judgment", "30 days from the date of judgment", "60 days from service of the claim"],
 "Article 18 sets fifteen days from the day following the hearing at which the judgment was issued, with a rule for absent defendants."),
("What is the status of a judgment of the Centre's Appellate Division?",
 "Final", ["Appealable to the Land Department", "Appealable to RERA", "Open to a second appeal"],
 "Article 14 makes Appellate Division judgments final and not subject to any form of appeal."),
]
